// Original passages retain source spelling and claims; only whitespace is normalized.
const passage = (
  id,
  year,
  title,
  pl,
  uk,
  original,
  originalUk,
  sourcePages,
  category,
  notePl = '',
  note = '',
) => ({
  id: `document-${id}`,
  year,
  title,
  pl,
  uk,
  original: original.replace(/\s+/gu, ' ').trim(),
  originalUk,
  note,
  notePl,
  date: '',
  source,
  category,
  sourcePages,
});

